import{z as n,x as o,o as t,c as p,q as r,j as l,D as E,d as s,s as B,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"卫星与高延迟链路","description":"","frontmatter":{"title":"卫星与高延迟链路","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/satellite-latency.md","filePath":"cs/satellite-latency.md","lastUpdated":1791063341000}'),d={name:"cs/satellite-latency.md"};function T(m,a,C,D,F,c){const A=o("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="卫星与高延迟链路" tabindex="-1">卫星与高延迟链路 <a class="header-anchor" href="#卫星与高延迟链路" aria-label="Permalink to &quot;卫星与高延迟链路&quot;">​</a></h1><div class="epigraph"><p>同步轨道一轮 RTT 以数百毫秒计，带宽时延积撑大窗口；丢包若被当成拥塞，TCP 会把空管道当成忙。</p><footer>—— 据 RFC 2488 卫星上的 TCP；ITU-R 卫星链路预算通识；Kurose and Ross 延迟带宽节整理</footer></div><p><a href="/cs/5g-slicing">上一课</a> 把地面蜂窝时延做到毫秒级合同。卫星把传播时延重新变成主导。缺口是<strong>高延迟链路</strong>：GEO 长 RTT、LEO 切换与变化 RTT；<a href="/cs/tcp-congestion">拥塞控制</a> 的丢包假设在此破裂。本课结束「无线与广域」；下一单元域内路由。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(C\\) 仍由功率与带宽决定（链路预算、雨衰），但 BDP \\(=C\\times\\mathrm{RTT}\\) 可达兆字节。窗口缩放后课才细讲；这里先钉：默认 64 KiB 窗口喂不饱卫星。随机误码使 AIMD 减窗，吞吐塌在远低于 \\(C\\) 处——PEPs、编码、或延迟型/基于容量的拥塞（后课 BBR）是对策方向。LEO：时延小但路径变，会话迁移像后课 QUIC 迁移的物理版。</p><p>不要把「卫星网」写成以太网：没有 PACING 的 PAUSE 能跨 36000 km 有用地工作。</p><p><span class="marginnote">RFC 2488 收集卫星 TCP 建议。GEO 约 250 ms 单程量级。本课不把星座路由协议写完。</span></p><p><span class="marginnote">数字实例：GEO 单程约 250 ms，RTT 就是 500 ms。100 Mbps 链路的带宽时延积 \\(=100\\,\\mathrm{Mb/s}\\times0.5\\,\\mathrm{s}=50\\) Mb \\(\\approx\\) 6.25 MB——而 TCP 默认 64 KiB 窗口只装得下百分之一，管道其余部分全在空跑。</span></p><p><span class="marginnote">直觉类比：把 BDP 想象成一条超长输油管的容积。发端把窗口里的油全灌进管子后必须等「反馈」回来才能加下一批；窗口比管子小，管子永远没满——这就是「窗口喂不饱链路」。</span></p><p><span class="marginnote">常见误区：初学者容易以为丢包都等于网络堵了。卫星链路的比特错误来自雨衰与宇宙射线，是「随机误码」——把这种丢包当成拥塞去减窗，管道明明空闲却被 AIMD 抽空。</span></p><h3 id="痛点常是-rtt-不是" tabindex="-1">痛点常是 RTT 不是 \\(C\\) <a class="header-anchor" href="#痛点常是-rtt-不是" aria-label="Permalink to &quot;痛点常是 RTT 不是 $C$&quot;">​</a></h3><p>BDP 撑大窗口；随机误码若当拥塞则 AIMD 抽空。PAUSE 跨 GEO 无用。LEO 切换更像路径迁移。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：光纤 5 μs/km vs GEO 固定长延迟。画：预算 → \\(C\\)；RTT → BDP；误码 → 勿当拥塞。巨型帧摊头税在此有用，但重传一整帧更痛，FEC 更重要。</p>',14)),(t(),l(i,null,{default:E(()=>[B(A,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUD%5B%22%E9%93%BE%E8%B7%AF%E9%A2%84%E7%AE%97%E5%BE%97%20C%22%5D%20--%3E%20BDP%5B%22C%20%E4%B9%98%20RTT%22%5D%0A%20%20BDP%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%E5%BF%85%E9%A1%BB%E5%96%82%E9%A5%B1%22%5D%0A%20%20BER%5B%22%E9%9A%8F%E6%9C%BA%E8%AF%AF%E7%A0%81%22%5D%20--%3E%20CC%5B%22%E5%8B%BF%E5%BD%93%E6%8B%A5%E5%A1%9E%E5%87%8F%E7%AA%97%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"蜂窝 URLLC 与卫星是时延谱的两端。主干分层仍成立：物理做 FEC，传输做窗口，应用做 FEC 或重试。生成树不会跨卫星广播域去算——IP 路由才行。测量后课的 ping 在此直接读到传播下限。",-1)),a[5]||(a[5]=e("p",null,"LEO 网关切换：IP 锚若在地面关口，类似蜂窝核心；若星上转发，拓扑动态更像后课流量工程。",-1)),(t(),l(i,null,{default:E(()=>[B(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOSS%5B%22%E8%A7%82%E6%B5%8B%E5%88%B0%E4%B8%A2%E5%8C%85%22%5D%20--%3E%20WHY%7B%22%E5%8E%9F%E5%9B%A0%E6%98%AF%E4%BB%80%E4%B9%88%3F%22%7D%0A%20%20WHY%20--%20%22%E7%BC%93%E5%86%B2%E5%8C%BA%E6%8C%A4%E6%BB%A1%22%20--%3E%20CC%5B%22%E5%BD%93%E6%8B%A5%E5%A1%9E%3A%20AIMD%20%E5%87%8F%E7%AA%97%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20WHY%20--%20%22%E9%9B%A8%E8%A1%B0%2F%E8%AF%AF%E7%A0%81%E6%89%93%E5%9D%8F%E5%B8%A7%22%20--%3E%20NOT%5B%22%E4%B8%8D%E6%98%AF%E6%8B%A5%E5%A1%9E%22%5D%0A%20%20NOT%20--%3E%20FEC%5B%22%E7%89%A9%E7%90%86%E5%B1%82%20FEC%20%E5%89%8D%E5%90%91%E7%BA%A0%E9%94%99%22%5D%0A%20%20WHY%20--%20%22%E7%AA%97%E5%8F%A3%E6%AF%94%20BDP%20%E5%B0%8F%22%20--%3E%20SCALE%5B%22%E5%BC%80%E7%AA%97%E5%8F%A3%E7%BC%A9%E6%94%BE%2C%20%E5%96%82%E9%A5%B1%E7%AE%A1%E9%81%93%22%5D%0A%20%20WHY%20--%20%22LEO%20%E5%8D%AB%E6%98%9F%E7%A7%BB%E5%87%BA%E8%A7%86%E8%B7%9D%22%20--%3E%20MIG%5B%22%E8%B7%AF%E5%BE%84%E8%BF%81%E7%A7%BB%3A%20%E6%8D%A2%E8%B7%AF%E4%B8%8D%E9%87%8D%E8%BF%9E%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>这张图回答的问题是：卫星链路上同一个「丢包」现象有四种成因，处理动作完全不同——把误码或小窗口当成拥塞去减窗，是 GEO 链路吞吐塌方最常见的误诊。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入深空 DTN 捆绑层全文。OSPF 区域与 LSA 是下一单元第一课。后课默认：高 RTT 链路用 BDP 与误码模型约束 TCP，不沿用局域网直觉。</p><p>监管与频谱许可约束真实 \\(B\\)，与 Wi‑Fi ISM 不同。</p><p>下一课<a href="/cs/ospf-areas-lsa">OSPF 区域与 LSA</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>卫星 \\(C\\) 来自功率带宽；痛点常是 RTT 与误码。</li><li>丢包≠拥塞时 AIMD 低估容量。</li><li>物理 FEC 与大窗口是配套，PAUSE 无用。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2488；ITU-R 链路预算；Kurose and Ross。</li></ul>',7))])}const u=n(d,[["render",T]]);export{P as __pageData,u as default};
